import { mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import type { AppConfig } from '../config.js';

/** Stored names are generated by us (uuid + extension), never taken from the upload. */
export const STORED_NAME = /^[0-9a-f-]{36}\.(pdf|docx)$/;

const dir = (config: AppConfig) => resolve(config.STORAGE_DIR, 'knowledge');

const pathOf = (config: AppConfig, storedName: string): string => {
  if (!STORED_NAME.test(storedName)) throw new Error('Invalid stored file name');
  return join(dir(config), storedName);
};

export const saveFile = async (config: AppConfig, storedName: string, data: Buffer): Promise<void> => {
  await mkdir(dir(config), { recursive: true, mode: 0o700 });
  await writeFile(pathOf(config, storedName), data, { mode: 0o600, flag: 'wx' });
};

export const readStoredFile = (config: AppConfig, storedName: string): Promise<Buffer> =>
  readFile(pathOf(config, storedName));

export const storedFilePath = pathOf;

export const deleteFile = async (config: AppConfig, storedName: string): Promise<void> => {
  await unlink(pathOf(config, storedName)).catch(() => undefined);
};
